create or replace function public.gateway_orchestration_trace_guard() returns trigger language plpgsql security definer set search_path=public as $$ declare v_user uuid; begin if new.tenant_id is null then raise exception 'gateway_trace_tenant_required'; end if; if new.transaction_id is null then raise exception 'gateway_trace_transaction_required'; end if; select user_id into v_user from public.gateway_transactions where id=new.transaction_id; if v_user is null then raise exception 'gateway_trace_transaction_not_found'; end if; if v_user<>new.tenant_id then raise exception 'gateway_trace_tenant_mismatch'; end if; if tg_op='UPDATE' then if old.tenant_id<>new.tenant_id or old.transaction_id<>new.transaction_id then raise exception 'gateway_trace_identity_immutable'; end if; end if; return new; end; $$; drop trigger if exists trg_gateway_orchestration_trace_guard on public.gateway_orchestration_traces; create trigger trg_gateway_orchestration_trace_guard before insert or update on public.gateway_orchestration_traces for each row execute function public.gateway_orchestration_trace_guard(); revoke all on function public.gateway_orchestration_trace_guard() from public,anon,authenticated; grant execute on function public.gateway_orchestration_trace_guard() to service_role; create index if not exists idx_gateway_orchestration_traces_tenant_transaction on public.gateway_orchestration_traces(tenant_id,transaction_id);